      '行程從安波塞利吉力馬札羅山下平原上的象群開篇，隨後是在馬賽馬拉度過的一晚與一個完整的日子——包括其馬拉河渡河領地——之後經伊西班尼亞陸路邊境穿越，將您從肯亞無縫帶入坦尚尼亞的塞倫蓋蒂，二者在生態上本是一片連續的景觀，儘管中間隔著一道政治邊界。塞倫蓋蒂獵豹與獅子領地兩個完整的日子，隨後是恩戈羅恩戈羅火山口內完整的一天，以及在馬尼亞拉湖的一次停留，那裡的樹棲獅群是東非其他任何地方都無法見到的獨特行為。全程提供舒適與高階兩個等級，這份精華行程正是為那些希望不打折扣地體驗兩國標誌性景觀的旅行者、尤其是攝影師而打造。',
